\documentclass{article}
\usepackage{pgfplots,amsmath}
\begin{document}
	\pagestyle{empty}

	\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
	\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
	\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
	\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
	\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
	\definecolor{rustred}{rgb}{0.784,0.392,0.149}
	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

	\begin{tikzpicture}

	\begin{axis}[
	tick label style={font=\footnotesize},
	label style={font=\small},
	tick style={line width=0.8pt, color=black},
	axis line style = thick,
	axis y line = center,
	axis x line = middle,
	xmin = -5.25,
	xmax = 3.25,
	ymin = -6.25,
	ymax = 6.25,
	xtick={-1},
	ytick={2},
	xlabel = $s$,
	ylabel = {$F(s)$},
	x tick label style={xshift={(\tick==-1)*-8pt}},
	y tick label style={yshift={(\tick==2)*4pt}},
	x label style={right},
	y label style={above},
	every axis x label/.style={
		at={(ticklabel* cs:1.02)},
		anchor=west,
	},
	every axis y label/.style={
		at={(ticklabel* cs:1.02)},
		anchor=south,
	}
	]

	% Curve: left shift by 2, F(s+2)
%	\addplot [domain=-5.25:-1.10, samples=300, color=deepskyblue, line width=1pt]
%	{(2*(x+2) - 3)/((x+2) - 1)};
	\addplot [domain=-0.90:3.25, samples=300, color=deepskyblue, line width=1pt]
	{(2*(x+2) - 3)/((x+2) - 1)};

	%% H.A. at y=2
	\addplot [domain=-5.25:3.25, samples=300,line width=0.5pt, dashed, color=black,opacity=0.25] {2};

	% Vertical Asymptote now at s=-1
	\addplot [color=black,line width=0.5pt,dashed, opacity=0.25] coordinates {(-1, -15) (-1,15)};

	\end{axis}
	\end{tikzpicture}
\end{document}
